import React from 'react'

export default function DependantPrescriptionHistory({dependantPrescriptions}) {
  return (
    <div>
    {dependantPrescriptions && dependantPrescriptions.length ? (
        <div>
          <p className="text-center text-1xl font-semibold">
            Prescriptions History: {dependantPrescriptions.length}
          </p>
          <div className="grid grid-cols-1 md:grid-cols-2 border-1 border-green-200 rounded-md shadow-md gap-4 gap-y-6">
            {dependantPrescriptions.map((prescription) => {
              return (
                <div className="grid grid-cols-1 w-full shadow-md border-1 border-gray-200 rounded-md gap-2 uppercase gap-2">
                  <div className="grid grid-cols-2">
                    <div>
                      <p className="font-bold">Date</p>
                      <p>{prescription.created}</p>
                    </div>
                    <div>
                      <p className="font-bold">Pharmacy</p>
                      <p>{prescription.entity_sub_store_name}</p>
                    </div>
                    <div>
                      <p className="font-bold">Closed</p>
                      <p>{prescription.is_closed}</p>
                    </div>
                    <div>
                      <p className="font-bold">Prescriber</p>
                      <p>{prescription.prescriber_name}</p>
                    </div>
                  </div>

                  <div className=" shadow-md rounded-md">
                    <p className="text-center uppercase">Items</p>
                    <div className="w-full grid gap-2 gap-y-4 p-2 bg-gray-100">
                      {prescription.items.map((item, index) => {
                        return (
                          <div className="grid grid-cols-2 rounded-md uppercase border-2 border-gray-300 shadow-md">
                            <div className="grid grid-cols-1 grid-flow-row border-1 border-gray-200">
                              <p className="font-bold">Route</p>
                              <p>{item.route_title}</p>
                            </div>
                            <div className="grid grid-cols-1 grid-flow-row border-1 border-gray-200">
                              <p className="font-bold">Item</p>
                              <span>{item.product_title}</span>
                            </div>
                            <div className="grid grid-cols-1 grid-flow-row border-1 border-gray-200">
                              <p className="font-bold">Dose</p>
                              <p>{item.dose}</p>
                            </div>
                            <div className="grid grid-cols-1 grid-flow-row border-1 border-gray-200">
                              <p className="font-bold">Frequency</p>
                              <p>{item.frequency_title}</p>
                            </div>
                            <div className="grid grid-cols-1 grid-flow-row border-1 border-gray-200">
                              <p className="font-bold">Days</p>
                              <p>{item.days}</p>
                            </div>
                            <div className="grid grid-cols-1 grid-flow-row border-1 border-gray-200">
                              <p className="font-bold">Instruction</p>
                              <p>{item.instruction}</p>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      ) : (
        <div>
          <p>No previous prescriptions</p>
        </div>
      )}
    
    </div>
  )
}
